using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Linq;using System.Collections.Generic;
internal sealed class ImageSwatch{public string Hex,Name,Kind;public double Share;public float X,Y;}
internal sealed class PaletteAssignment{public string Primary,Secondary,Neutral,Accent;public PaletteAssignment Copy(){return (PaletteAssignment)MemberwiseClone();}}
internal static partial class SmartPalette{
 struct SamplePoint{public Color Color;public Oklab Lab;public float X,Y;}
 static double Delta(Oklab a,Oklab b){return (a.L-b.L)*(a.L-b.L)+(a.A-b.A)*(a.A-b.A)+(a.B-b.B)*(a.B-b.B);}
 internal static ImageSwatch[] ExtractImagePalette(string path){
  var points=new List<SamplePoint>();using(var im=Image.FromFile(path)){double scale=Math.Min(1,192d/Math.Max(im.Width,im.Height));int w=Math.Max(1,(int)(im.Width*scale)),h=Math.Max(1,(int)(im.Height*scale));using(var b=new Bitmap(w,h)){using(var g=Graphics.FromImage(b)){g.CompositingMode=CompositingMode.SourceCopy;g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(im,0,0,w,h);}for(int y=0;y<h;y++)for(int x=0;x<w;x++){Color c=b.GetPixel(x,y);if(c.A>=200)points.Add(new SamplePoint{Color=c,Lab=ToOk(c),X=x/(float)Math.Max(1,w-1),Y=y/(float)Math.Max(1,h-1)});}}}
  if(points.Count==0)throw new InvalidDataException("图片没有不透明的可取色区域。");
  var ps=points.ToArray();int k=Math.Min(22,ps.Length);var centers=new Oklab[k];centers[0]=ps[ps.Length/2].Lab;
  for(int i=1;i<k;i++){double far=-1;int best=0;for(int n=0;n<ps.Length;n++){double near=double.MaxValue;for(int j=0;j<i;j++)near=Math.Min(near,Delta(ps[n].Lab,centers[j]));if(near>far){far=near;best=n;}}centers[i]=ps[best].Lab;}
  var assigned=new int[ps.Length];var counts=new int[k];
  for(int pass=0;pass<9;pass++){Array.Clear(counts,0,k);var totals=new double[k,3];for(int n=0;n<ps.Length;n++){double near=double.MaxValue;int best=0;for(int j=0;j<k;j++){double d=Delta(ps[n].Lab,centers[j]);if(d<near){near=d;best=j;}}assigned[n]=best;counts[best]++;totals[best,0]+=ps[n].Lab.L;totals[best,1]+=ps[n].Lab.A;totals[best,2]+=ps[n].Lab.B;}for(int j=0;j<k;j++)if(counts[j]>0)centers[j]=new Oklab{L=totals[j,0]/counts[j],A=totals[j,1]/counts[j],B=totals[j,2]/counts[j]};}
  var candidates=new List<ImageSwatch>();for(int j=0;j<k;j++){double share=counts[j]/(double)ps.Length;if(share<.0035)continue;int nearest=-1;double dist=double.MaxValue;for(int n=0;n<ps.Length;n++)if(assigned[n]==j){double d=Delta(ps[n].Lab,centers[j]);if(d<dist){dist=d;nearest=n;}}if(nearest<0)continue;var p=ps[nearest];candidates.Add(new ImageSwatch{Hex=Hex(p.Color),Name=ColorName(p.Color),Kind=p.Lab.C>.09?"彩色重点":p.Lab.L>.7?"浅色层次":"基底色",Share=share,X=p.X,Y=p.Y});}
  var salient=ps.Where(p=>p.Lab.C>.045&&p.Lab.L>.38&&p.Lab.L<.88).GroupBy(p=>(int)(p.Color.GetHue()/30)*6+(p.Lab.L<.5?0:p.Lab.L<.68?1:2)+(p.Color.GetSaturation()<.75?3:0)).Where(g=>g.Count()>=Math.Max(3,ps.Length*((g.First().Color.GetHue()>90&&g.First().Color.GetHue()<300)?.001:.004))).Select(g=>{var v=g.OrderByDescending(p=>p.Lab.C*(1-Math.Abs(p.Lab.L-.6))).First();return new ImageSwatch{Hex=Hex(v.Color),Name=ColorName(v.Color),Kind="鲜艳重点",Share=g.Count()/(double)ps.Length,X=v.X,Y=v.Y};}).OrderByDescending(c=>ToOk(ColorTranslator.FromHtml(c.Hex)).C*Math.Pow(c.Share,.25)).ToArray();
  var chosen=new List<ImageSwatch>();Action<ImageSwatch> add=s=>{if(s==null||chosen.Any(c=>Delta(ToOk(ColorTranslator.FromHtml(c.Hex)),ToOk(ColorTranslator.FromHtml(s.Hex)))<.0030))return;if(chosen.Count(c=>ColorName(ColorTranslator.FromHtml(c.Hex))==s.Name)>=(s.Name=="绯红"?2:1))return;if(ToOk(ColorTranslator.FromHtml(s.Hex)).L<.3&&chosen.Count(c=>ToOk(ColorTranslator.FromHtml(c.Hex)).L<.3)>=1)return;chosen.Add(s);};
  // Area and chroma get separate quotas: an all-dark majority cannot bury the
  // colorful objects, and isolated bright pixels cannot replace the base colors.
  Func<SamplePoint,string,ImageSwatch> representative=(v,kind)=>{int n=Array.IndexOf(ps,v);return new ImageSwatch{Hex=Hex(v.Color),Name=ColorName(v.Color),Kind=kind,Share=n<0?0:counts[assigned[n]]/(double)ps.Length,X=v.X,Y=v.Y};};
  foreach(var dominant in candidates.Where(c=>c.Share>=.12).OrderByDescending(c=>c.Share))add(dominant);
  var huePopulation=new int[24];foreach(var point in ps)if(point.Lab.C>.045&&point.Lab.L>.3&&point.Lab.L<.9)huePopulation[Math.Min(23,(int)(point.Color.GetHue()/15))]++;
  var strong=ps.Where(v=>huePopulation[Math.Min(23,(int)(v.Color.GetHue()/15))]>=Math.Max(8,ps.Length*.006)&&v.Lab.C>.09&&v.Lab.L>.43&&v.Lab.L<.82).OrderByDescending(v=>v.Lab.C*(1-Math.Abs(v.Lab.L-.6))).ToArray();
  if(strong.Length>0){var anchor=strong[0];add(representative(anchor,"鲜艳重点"));var softs=ps.Where(v=>v.Lab.L>.58&&v.Lab.L<.78&&v.Lab.C>.07&&v.Lab.C<.17&&Math.Abs((v.Lab.Hue-anchor.Lab.Hue+540)%360-180)<14).OrderBy(v=>Math.Abs(v.Lab.L-.68)+Math.Abs(v.Lab.C-.13)).ToArray();if(softs.Length>0)add(representative(softs[0],"柔和重点"));}
  var cool=ps.Where(v=>v.Color.GetHue()>90&&v.Color.GetHue()<300&&v.Lab.C>.055&&v.Lab.L>.45&&v.Lab.L<.8).GroupBy(v=>(int)(v.Color.GetHue()/30)).Where(g=>g.Count()>=Math.Max(3,ps.Length*.001)).Select(g=>g.OrderByDescending(v=>v.Lab.C).First()).OrderByDescending(v=>v.Lab.C).ToArray();if(cool.Length>0)add(representative(cool[0],"对比点缀"));
  foreach(var c in salient){if(chosen.Count>=5)break;add(c);}
  foreach(var c in candidates.Where(c=>ToOk(ColorTranslator.FromHtml(c.Hex)).C>.075).OrderByDescending(c=>Math.Pow(c.Share,.55)*ToOk(ColorTranslator.FromHtml(c.Hex)).C).Take(2))add(c);
  foreach(var c in candidates.Where(c=>ToOk(ColorTranslator.FromHtml(c.Hex)).L>.68).OrderByDescending(c=>c.Share).Take(2))add(c);
  foreach(var c in candidates.OrderByDescending(c=>c.Share))if(chosen.Count<10)add(c);
  return chosen.Take(10).ToArray();
 }
 static string ColorName(Color c){double h=c.GetHue(),s=c.GetSaturation(),l=c.GetBrightness();var lab=ToOk(c);if(lab.C<.06&&lab.L>.65)return lab.L>.83?"柔白":"暖灰米色";if(s<.13)return l<.23?"石墨黑":l>.78?"柔白":"中性灰";if(l<.18)return "深色基底";if(h<12||h>=345)return l>.55?"珊瑚粉":"绯红";if(h<35)return l>.55?"珊瑚橘":l<.5?"暖棕":"朱红";if(h<65)return l>.7?"奶油白":"琥珀金";if(h<165)return "植物绿";if(h<205)return "湖水青";if(h<265)return "冷调蓝";if(h<300)return "暮紫";return "玫瑰红";}
 internal static PaletteAssignment AssignPalette(ImageSwatch[] palette){if(palette.Length==0)throw new ArgumentException("palette");var colorful=palette.Where(c=>ToOk(ColorTranslator.FromHtml(c.Hex)).C>.075).ToArray();var primary=(colorful.Length>0?colorful:palette).OrderByDescending(c=>Math.Pow(c.Share,.55)*Math.Max(.03,ToOk(ColorTranslator.FromHtml(c.Hex)).C)).First();var mainLab=ToOk(ColorTranslator.FromHtml(primary.Hex));var related=palette.Where(c=>{var v=ToOk(ColorTranslator.FromHtml(c.Hex));double gap=Math.Abs((v.Hue-mainLab.Hue+540)%360-180);return c.Hex!=primary.Hex&&c.Share>=.006&&v.L>.25&&v.L<.9&&(v.C<.04||gap<45);}).ToArray();var secondary=related.OrderByDescending(c=>{var v=ToOk(ColorTranslator.FromHtml(c.Hex));double gap=v.C<.025?0:Math.Abs((v.Hue-mainLab.Hue+540)%360-180);return Math.Sqrt(c.Share)/(1+gap/35)*Math.Min(1,Math.Sqrt(Delta(v,mainLab))*8);}).FirstOrDefault()??primary;var neutral=palette.OrderBy(c=>ToOk(ColorTranslator.FromHtml(c.Hex)).C*.6+Math.Abs(ToOk(ColorTranslator.FromHtml(c.Hex)).L-.27)).First();var accent=palette.Where(c=>c.Hex!=primary.Hex&&c.Hex!=secondary.Hex&&ToOk(ColorTranslator.FromHtml(c.Hex)).L>.55&&Delta(ToOk(ColorTranslator.FromHtml(c.Hex)),ToOk(ColorTranslator.FromHtml(primary.Hex)))>.012).OrderByDescending(c=>c.Share).FirstOrDefault()??secondary;return new PaletteAssignment{Primary=primary.Hex,Secondary=secondary.Hex,Neutral=neutral.Hex,Accent=accent.Hex};}
 internal static SmartColors GenerateMapped(string path,int variant,int mode,PaletteAssignment map,ImageSwatch[] imagePalette){var p=Generate(path,variant==3?0:variant,mode,map.Primary);p.Variant=variant;Color text=ColorTranslator.FromHtml(p.Text);var secondary=ToOk(ColorTranslator.FromHtml(map.Secondary));var neutral=ToOk(ColorTranslator.FromHtml(map.Neutral));var accent=ToOk(ColorTranslator.FromHtml(map.Accent));p.Theme.Colors[14+mode]=Hex(mode==1?Surface(secondary.Hue,Math.Min(.045,secondary.C*.25),.29,text):VividLightSurface(secondary.Hue,Math.Min(.055,secondary.C*.3),.95,text));double[] dark={.19,.22,.17,.25,.16},light={.95,.97,.985,.94,.91};for(int i=0;i<5;i++)p.Theme.Colors[i*2+mode]=Hex(Tone(neutral.Hue,Math.Min(.018,neutral.C*.12),mode==1?dark[i]:light[i]));Color target=Tone(accent.Hue,Math.Min(.14,accent.C),mode==1?.83:.40);Color selected=ColorTranslator.FromHtml(p.Theme.Colors[10+mode]);target=Readable(target,selected,3,mode==1);p.Accent=Hex(target);p.Samples=imagePalette.Select(c=>c.Hex).ToArray();if(variant==0)ApplyReferenceHarmony(p,map);else if(variant==3)ApplyImageHarmony(p,map);if(mode==0)ApplyLightHierarchy(p,map);p.Description=variant==0?"参考图协调：低亮度主色、深暖副色、暖白文字；鲜艳颜色仅作点缀。":"整图多色方案：主色用于发送与选中，副色用于接收，基底色用于页面，点缀色用于强调图标。";TuneUiContrast(path,p,map);p.InputOpacity=0;return p;}
}
